draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // draw two circles for the 2's
  ctx.beginPath();
  ctx.arc(W/4 + 20*Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/4 + 50 + 20*Math.sin(t+Math.PI), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  // draw zero circle
  ctx.beginPath();
  ctx.arc(W*3/4 + 20*Math.cos(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.restore();
}
